from coursekit import PROVIDERS

council = {  # same job and sources; a different stance and model provider for each architect
    "Minimalist": {"provider": "freeinference", "stance": "Prefer the simplest design that meets the requirements."},
    "Safeguard": {"provider": "deepseek", "stance": "Prefer low-risk designs; weigh operations and failures."},
    "Modernizer": {"provider": "gemini", "stance": "Prefer designs that let each squad change and release alone."},
}
families = {name: PROVIDERS[a["provider"]]["family"] for name, a in council.items()}
assert len(set(families.values())) >= 3, "The council needs at least three model families."
asks = {name: make_ask(mode=MODE, provider=a["provider"]) for name, a in council.items()}
print(families)

def say(name, task, example):
    """Ask one architect: its role and stance, the shared sources, then the task."""
    role = f"You are the {name} on an architecture council. {council[name]['stance']}"
    return asks[name](f"{role}\nSources:\n{evidence}\n{task}", example=example)

import json
from concurrent.futures import ThreadPoolExecutor

REPLY = 'Reply with JSON only, no code fences: {"option": "...", "claim": "one sentence", "evidence": ["ids"]}'
scripted = {
    "Minimalist": '{"option": "microservices", "claim": "Squads that release alone meet R1.", "evidence": ["R1", "F2"]}',
    "Safeguard": '{"option": "modular monolith", "claim": "One engineer cannot run many services.", "evidence": ["F3"]}',
    "Modernizer": '{"option": "microservices", "claim": "Microservices make payments faster.", "evidence": []}',
}

def propose(name):
    """One architect answers alone: the prompt never contains another proposal."""
    task = f"Choose modular monolith or microservices for the Payments platform. {REPLY}"
    return {"round": 1, "speaker": name, "kind": "proposal", **json.loads(say(name, task, scripted[name]))}

with ThreadPoolExecutor() as pool:  # the three architects work at the same time
    proposals = {message["speaker"]: message for message in pool.map(propose, council)}
for m in proposals.values():
    print(f"{m['speaker']:<11} {m['option']:<17} {str(m['evidence']):<19} {m['claim']}")
